#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Attempts, in order:
  1. Python libraries: pypdf, PyPDF2, fitz (PyMuPDF)
  2. Command-line tools: pdfunite (poppler), qpdf, pdftk, gs (ghostscript)
"""
import os
import shutil
import subprocess
import sys

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"


def merge_with_pypdf_like(module_name):
    mod = __import__(module_name)
    reader_cls = mod.PdfReader
    writer_cls = mod.PdfWriter
    writer = writer_cls()
    page_count = 0
    for pdf_file in INPUT_FILES:
        reader = reader_cls(pdf_file)
        for page in reader.pages:
            writer.add_page(page)
            page_count += 1
    with open(OUTPUT_FILE, "wb") as output:
        writer.write(output)
    print(f"Merged via {module_name}: {OUTPUT_FILE} with {page_count} pages.")
    return True


def merge_with_fitz():
    import fitz

    out = fitz.open()
    page_count = 0
    for pdf_file in INPUT_FILES:
        src = fitz.open(pdf_file)
        out.insert_pdf(src)
        page_count += src.page_count
        src.close()
    out.save(OUTPUT_FILE)
    out.close()
    print(f"Merged via fitz: {OUTPUT_FILE} with {page_count} pages.")
    return True


def run_tool(cmd):
    """Run a command; return (ok, stdout+stderr)."""
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        combined = (proc.stdout or "") + (proc.stderr or "")
        return proc.returncode == 0, combined.strip()
    except FileNotFoundError:
        return False, f"tool not found: {cmd[0]}"
    except Exception as exc:
        return False, f"{type(exc).__name__}: {exc}"


def merge_via_pdfunite():
    ok, msg = run_tool(["pdfunite"] + INPUT_FILES + [OUTPUT_FILE])
    if ok:
        print(f"Merged via pdfunite: {OUTPUT_FILE}")
    else:
        print(f"pdfunite failed: {msg}", file=sys.stderr)
    return ok


def merge_via_qpdf():
    ok, msg = run_tool(
        ["qpdf", "--empty", "--pages"] + INPUT_FILES + ["--", OUTPUT_FILE]
    )
    if ok:
        print(f"Merged via qpdf: {OUTPUT_FILE}")
    else:
        print(f"qpdf failed: {msg}", file=sys.stderr)
    return ok


def merge_via_pdftk():
    ok, msg = run_tool(
        ["pdftk"] + INPUT_FILES + ["cat", "output", OUTPUT_FILE]
    )
    if ok:
        print(f"Merged via pdftk: {OUTPUT_FILE}")
    else:
        print(f"pdftk failed: {msg}", file=sys.stderr)
    return ok


def merge_via_gs():
    ok, msg = run_tool(
        [
            "gs", "-dBATCH", "-dNOPAUSE", "-sDEVICE=pdfwrite",
            f"-sOutputFile={OUTPUT_FILE}",
        ] + INPUT_FILES
    )
    if ok:
        print(f"Merged via gs: {OUTPUT_FILE}")
    else:
        print(f"gs failed: {msg}", file=sys.stderr)
    return ok


def main():
    if not all(os.path.isfile(f) for f in INPUT_FILES):
        print(f"ERROR: missing input file(s); cwd={os.getcwd()}", file=sys.stderr)
        print("Files in cwd:", os.listdir("."), file=sys.stderr)
        return 1

    attempts = [
        ("pypdf", merge_with_pypdf_like, ("pypdf",)),
        ("PyPDF2", merge_with_pypdf_like, ("PyPDF2",)),
        ("fitz", merge_with_fitz, ()),
        ("pdfunite", merge_via_pdfunite, ()),
        ("qpdf", merge_via_qpdf, ()),
        ("pdftk", merge_via_pdftk, ()),
        ("gs", merge_via_gs, ()),
    ]
    for name, fn, args in attempts:
        try:
            if fn(*args):
                if os.path.isfile(OUTPUT_FILE) and os.path.getsize(OUTPUT_FILE) > 0:
                    print(
                        f"SUCCESS: {OUTPUT_FILE} created "
                        f"({os.path.getsize(OUTPUT_FILE)} bytes)"
                    )
                    return 0
                print(f"WARNING: {name} reported success but output missing", file=sys.stderr)
        except Exception as exc:
            print(f"{name} failed: {type(exc).__name__}: {exc}", file=sys.stderr)

    print("ERROR: all merge strategies failed", file=sys.stderr)
    return 1


if __name__ == "__main__":
    sys.exit(main())

